changeSet.sql:
CREATE TABLE goods_receipt (
 id uuid PRIMARY KEY,
 invoice_id uuid NOT NULL UNIQUE REFERENCES sef_invoice(id),
 stock_location_id uuid NOT NULL REFERENCES stock_location(id),
 status varchar(30) NOT NULL CHECK (status IN ('PENDING', 'PARTIAL', 'RECEIVED')),
 created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, version bigint NOT NULL DEFAULT 0
);
CREATE TABLE goods_receipt_line (
 id uuid PRIMARY KEY, receipt_id uuid NOT NULL REFERENCES goods_receipt(id),
 line_number integer NOT NULL, item_name varchar(500) NOT NULL, seller_item_id varchar(120), unit_code varchar(40),
 expected_quantity numeric(14,3) NOT NULL CHECK (expected_quantity > 0),
 received_quantity numeric(14,3) NOT NULL DEFAULT 0 CHECK (received_quantity >= 0 AND received_quantity <= expected_quantity),
 purchase_price numeric(14,4), vat_rate numeric(5,2), retail_price numeric(12,2),
 product_id uuid REFERENCES product(id), status varchar(30) NOT NULL CHECK (status IN ('PENDING', 'PARTIAL', 'RECEIVED')),
 approved_by varchar(320), approved_at timestamptz,
 UNIQUE (receipt_id, line_number)
);
ALTER TABLE stock_movement ADD COLUMN receipt_line_id uuid REFERENCES goods_receipt_line(id);
ALTER TABLE stock_movement ADD COLUMN receipt_retail_price numeric(12,2);
